/* ============================================
   LearnForge — Global Styles
   ============================================ */

:root {
  --color-primary: #000000;
  --color-accent: #E6FF32;
  --color-burgundy: #7F2A23;
  --color-white: #FFFFFF;
  --color-gray-50: #F9FAFB;
  --color-gray-100: #F3F4F6;
  --color-gray-200: #E5E7EB;
  --color-gray-300: #D1D5DB;
  --color-gray-400: #9CA3AF;
  --color-gray-500: #6B7280;
  --color-gray-600: #4B5563;
  --color-gray-700: #374151;
  --color-gray-800: #1F2937;
  --color-gray-900: #111827;

  --font-heading: 'Plus Jakarta Sans', 'Inter', system-ui, sans-serif;
  --font-body: 'Inter', system-ui, -apple-system, sans-serif;

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.08), 0 8px 10px -6px rgba(0,0,0,0.04);

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  color: var(--color-gray-900);
  background: var(--color-white);
  line-height: 1.6;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.02em;
}

/* Container */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

@media (min-width: 768px) {
  .container {
    padding: 0 32px;
  }
}

@media (min-width: 1024px) {
  .container {
    padding: 0 48px;
  }
}

/* ============================================
   Navigation
   ============================================ */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-gray-200);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--color-primary);
}

.nav-logo span {
  color: var(--color-burgundy);
}

.nav-links {
  display: none;
  gap: 32px;
  align-items: center;
}

.nav-links a {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-gray-600);
  transition: color var(--transition-fast);
}

.nav-links a:hover {
  color: var(--color-primary);
}

.nav-links a.active {
  color: var(--color-primary);
  font-weight: 600;
}

.nav-cta {
  display: none;
  background: var(--color-primary);
  color: var(--color-white);
  font-size: 0.9375rem;
  font-weight: 600;
  padding: 10px 22px;
  border-radius: var(--radius-full);
  transition: transform var(--transition-fast), box-shadow var(--transition-fast);
}

.nav-cta:hover {
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.nav-mobile-toggle {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}

.nav-mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-primary);
  border-radius: 2px;
  transition: var(--transition-base);
}

.nav-mobile-menu {
  display: none;
  flex-direction: column;
  gap: 4px;
  padding: 16px 24px 24px;
  border-top: 1px solid var(--color-gray-200);
}

.nav-mobile-menu.open {
  display: flex;
}

.nav-mobile-menu a {
  font-size: 1rem;
  font-weight: 500;
  color: var(--color-gray-700);
  padding: 10px 0;
}

.nav-mobile-menu .nav-cta-mobile {
  margin-top: 8px;
  background: var(--color-primary);
  color: var(--color-white);
  font-size: 1rem;
  font-weight: 600;
  padding: 12px;
  border-radius: var(--radius-full);
  text-align: center;
}

@media (min-width: 1024px) {
  .nav-links, .nav-cta {
    display: flex;
  }
  .nav-mobile-toggle, .nav-mobile-menu {
    display: none !important;
  }
}

/* ============================================
   Buttons
   ============================================ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-size: 1rem;
  font-weight: 600;
  padding: 14px 28px;
  border-radius: var(--radius-full);
  transition: transform var(--transition-fast), box-shadow var(--transition-fast), background var(--transition-fast);
  white-space: nowrap;
}

.btn:hover {
  transform: translateY(-2px);
}

.btn-primary {
  background: var(--color-primary);
  color: var(--color-white);
  box-shadow: var(--shadow-sm);
}

.btn-primary:hover {
  box-shadow: var(--shadow-md);
}

.btn-accent {
  background: var(--color-accent);
  color: var(--color-primary);
  box-shadow: var(--shadow-sm);
}

.btn-accent:hover {
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-gray-300);
}

.btn-outline:hover {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-sm);
}

.btn-white {
  background: var(--color-white);
  color: var(--color-primary);
  box-shadow: var(--shadow-sm);
}

.btn-white:hover {
  box-shadow: var(--shadow-md);
}

/* ============================================
   Hero
   ============================================ */
.hero {
  position: relative;
  padding: 80px 0 60px;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, var(--color-gray-50) 0%, var(--color-white) 50%, var(--color-gray-50) 100%);
  z-index: -1;
}

.hero-accent-shape {
  position: absolute;
  top: -10%;
  right: -5%;
  width: 500px;
  height: 500px;
  background: var(--color-accent);
  border-radius: 50%;
  opacity: 0.15;
  filter: blur(80px);
  z-index: -1;
}

.hero-inner {
  display: grid;
  gap: 48px;
  align-items: center;
}

@media (min-width: 1024px) {
  .hero-inner {
    grid-template-columns: 1fr 1fr;
    gap: 64px;
  }
}

.hero-title {
  font-size: clamp(2.25rem, 5vw, 3.75rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.03em;
  color: var(--color-primary);
  margin-bottom: 20px;
}

.hero-subtitle {
  font-size: clamp(1.0625rem, 2vw, 1.25rem);
  color: var(--color-gray-600);
  line-height: 1.6;
  margin-bottom: 32px;
  max-width: 520px;
}

.hero-ctas {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.hero-visual {
  position: relative;
}

.hero-tabs {
  display: inline-flex;
  background: var(--color-gray-100);
  border-radius: var(--radius-full);
  padding: 4px;
  margin-bottom: 20px;
}

.hero-tab {
  font-size: 0.875rem;
  font-weight: 600;
  padding: 8px 18px;
  border-radius: var(--radius-full);
  color: var(--color-gray-500);
  transition: all var(--transition-fast);
}

.hero-tab.active {
  background: var(--color-white);
  color: var(--color-primary);
  box-shadow: var(--shadow-sm);
}

.hero-preview {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  border: 1px solid var(--color-gray-200);
  overflow: hidden;
  min-height: 320px;
}

.hero-preview-panel {
  display: none;
  padding: 32px;
}

.hero-preview-panel.active {
  display: block;
  animation: fadeIn 0.35s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.preview-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 20px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--color-gray-100);
}

.preview-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}

.preview-dot.red { background: #EF4444; }
.preview-dot.yellow { background: #F59E0B; }
.preview-dot.green { background: #10B981; }

.preview-title {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--color-gray-400);
  margin-left: 4px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.preview-content {
  display: grid;
  gap: 12px;
}

.preview-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  background: var(--color-gray-50);
  border-radius: var(--radius-sm);
}

.preview-avatar {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-full);
  background: linear-gradient(135deg, var(--color-accent), #C8E600);
  flex-shrink: 0;
}

.preview-text {
  flex: 1;
}

.preview-text-line {
  height: 10px;
  background: var(--color-gray-200);
  border-radius: 4px;
  margin-bottom: 6px;
}

.preview-text-line.short {
  width: 60%;
}

.preview-badge {
  font-size: 0.6875rem;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: var(--radius-full);
  background: var(--color-accent);
  color: var(--color-primary);
}

.preview-badge.outline {
  background: transparent;
  border: 1px solid var(--color-gray-300);
  color: var(--color-gray-500);
}

.preview-progress {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
}

.preview-progress-bar {
  flex: 1;
  height: 6px;
  background: var(--color-gray-200);
  border-radius: 3px;
  overflow: hidden;
}

.preview-progress-fill {
  height: 100%;
  background: var(--color-accent);
  border-radius: 3px;
}

.preview-progress-text {
  font-size: 0.6875rem;
  color: var(--color-gray-400);
  font-weight: 500;
}

/* ============================================
   Stats Bar
   ============================================ */
.stats-bar {
  background: var(--color-primary);
  color: var(--color-white);
  padding: 40px 0;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  text-align: center;
}

.stat-value {
  font-family: var(--font-heading);
  font-size: clamp(1.5rem, 3.5vw, 2.5rem);
  font-weight: 800;
  color: var(--color-accent);
  letter-spacing: -0.02em;
}

.stat-label {
  font-size: 0.875rem;
  color: var(--color-gray-400);
  margin-top: 4px;
}

/* ============================================
   Section Base
   ============================================ */
.section {
  padding: 80px 0;
}

.section-alt {
  background: var(--color-gray-50);
}

.section-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto 56px;
}

.section-label {
  display: inline-block;
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-burgundy);
  margin-bottom: 12px;
}

.section-title {
  font-size: clamp(1.75rem, 4vw, 2.75rem);
  font-weight: 800;
  color: var(--color-primary);
  margin-bottom: 16px;
}

.section-desc {
  font-size: 1.0625rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* ============================================
   Cards
   ============================================ */
.card-grid {
  display: grid;
  gap: 24px;
}

.card-grid.three {
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

.card-grid.four {
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
}

.card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 1px solid var(--color-gray-200);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: var(--color-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  font-size: 1.25rem;
}

.card-icon.burgundy {
  background: var(--color-burgundy);
  color: var(--color-white);
}

.card-title {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: 8px;
  color: var(--color-primary);
}

.card-text {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* ============================================
   Product Cards (Home)
   ============================================ */
.product-card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 1px solid var(--color-gray-200);
  transition: all var(--transition-base);
  position: relative;
  overflow: hidden;
}

.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: var(--color-accent);
  transform: scaleX(0);
  transition: transform var(--transition-base);
}

.product-card:hover::before {
  transform: scaleX(1);
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.product-card-icon {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-md);
  background: var(--color-gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 20px;
}

.product-card-title {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.product-card-text {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
  line-height: 1.6;
  margin-bottom: 16px;
}

.product-card-link {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-primary);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.product-card-link::after {
  content: '→';
  transition: transform var(--transition-fast);
}

.product-card-link:hover::after {
  transform: translateX(4px);
}

/* ============================================
   Tabs (Why Choose Us)
   ============================================ */
.tabs-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
  margin-bottom: 40px;
}

.tab-btn {
  font-size: 0.9375rem;
  font-weight: 600;
  padding: 12px 20px;
  border-radius: var(--radius-full);
  color: var(--color-gray-500);
  background: var(--color-gray-100);
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.tab-btn:hover {
  color: var(--color-primary);
  background: var(--color-gray-200);
}

.tab-btn.active {
  background: var(--color-primary);
  color: var(--color-white);
}

.tab-panel {
  display: none;
  animation: fadeIn 0.35s ease;
}

.tab-panel.active {
  display: block;
}

.tab-content-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 20px;
}

.tab-feature {
  background: var(--color-white);
  border-radius: var(--radius-md);
  padding: 24px;
  border: 1px solid var(--color-gray-200);
}

.tab-feature-title {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.tab-feature-title::before {
  content: '✓';
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  background: var(--color-accent);
  color: var(--color-primary);
  border-radius: 50%;
  font-size: 0.75rem;
  font-weight: 700;
  flex-shrink: 0;
}

.tab-feature-text {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
  line-height: 1.5;
}

/* ============================================
   Testimonials Carousel
   ============================================ */
.testimonials {
  position: relative;
}

.testimonial-track {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  padding-bottom: 16px;
  -ms-overflow-style: none;
  scrollbar-width: none;
}

.testimonial-track::-webkit-scrollbar {
  display: none;
}

.testimonial-card {
  flex: 0 0 100%;
  scroll-snap-align: start;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 1px solid var(--color-gray-200);
}

@media (min-width: 640px) {
  .testimonial-card {
    flex: 0 0 calc(50% - 12px);
  }
}

@media (min-width: 1024px) {
  .testimonial-card {
    flex: 0 0 calc(33.333% - 16px);
  }
}

.testimonial-quote {
  font-size: 1.0625rem;
  line-height: 1.6;
  color: var(--color-gray-700);
  margin-bottom: 24px;
  font-style: italic;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 14px;
}

.testimonial-avatar {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-full);
  background: linear-gradient(135deg, var(--color-accent), #C8E600);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.875rem;
  color: var(--color-primary);
  flex-shrink: 0;
}

.testimonial-name {
  font-size: 0.9375rem;
  font-weight: 700;
  color: var(--color-primary);
}

.testimonial-role {
  font-size: 0.8125rem;
  color: var(--color-gray-400);
}

.testimonial-tag {
  display: inline-block;
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--color-burgundy);
  background: rgba(127, 42, 35, 0.08);
  padding: 4px 10px;
  border-radius: var(--radius-full);
  margin-bottom: 12px;
}

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 32px;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-white);
  border: 1px solid var(--color-gray-300);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.125rem;
  color: var(--color-primary);
  transition: all var(--transition-fast);
}

.carousel-btn:hover {
  background: var(--color-primary);
  color: var(--color-white);
  border-color: var(--color-primary);
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 16px;
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-gray-300);
  transition: all var(--transition-fast);
}

.carousel-dot.active {
  background: var(--color-primary);
  width: 24px;
  border-radius: 4px;
}

/* ============================================
   FAQ Accordion
   ============================================ */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.faq-item {
  background: var(--color-white);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-gray-200);
  overflow: hidden;
  transition: box-shadow var(--transition-base);
}

.faq-item.open {
  box-shadow: var(--shadow-md);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 20px 24px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-primary);
  text-align: left;
}

.faq-icon {
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: transform var(--transition-base);
}

.faq-item.open .faq-icon {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow), padding var(--transition-slow);
}

.faq-item.open .faq-answer {
  max-height: 300px;
  padding: 0 24px 20px;
}

.faq-answer p {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* ============================================
   Pricing
   ============================================ */
